        "timeout": "3s",
        "interval": "3s",
        "retries": 30,
        "start_period": "10s"
      },
      "image": "docker.io/library/mongo:8.0.29-noble@sha256:021b2d5ae9d253f2cca17491cc8d03aed8df3c840f3252066aa62d3277fc406e",
      "networks": {
        "core": {
          "ipv4_address": "10.53.0.2"
        }
      },
      "restart": "no",
      "volumes": [
        {
          "type": "volume",
          "source": "mongodb_data",
          "target": "/data/db",
          "volume": {}
        },
        {
          "type": "bind",
          "source": "C:\\Users\\devel\\Documents\\Codex\\2026-08-22\\he\\safetwin-5g\\sandbox\\config\\mongodb\\10-subscriber.js",
          "target": "/docker-entrypoint-initdb.d/10-subscriber.js",
          "read_only": true,
          "bind": {}
        }
      ]
    },
    "open5gs": {
      "build": {
        "context": "C:\\Users\\devel\\Documents\\Codex\\2026-08-22\\he\\safetwin-5g\\sandbox\\docker\\open5gs",
        "dockerfile": "Dockerfile",
        "args": {
          "OPEN5GS_COMMIT": "318eeb49a7dcdff733dec60e02d9c60aefca2fb9",
          "OPEN5GS_TAG": "v2.7.7"
        }
      },
      "cap_add": [
        "NET_ADMIN",
        "NET_RAW"
      ],
      "command": null,
      "container_name": "safetwin5g-open5gs",
      "depends_on": {
        "mongodb": {
          "condition": "service_healthy",
          "required": true
        }
      },
      "devices": [
        {
          "source": "/dev/net/tun",
          "target": "/dev/net/tun",
          "permissions": "rwm"
        }
      ],
      "entrypoint": null,
      "healthcheck": {
        "test": [
          "CMD-SHELL",
          "curl --fail --silent http://10.53.0.3:9090/metrics \u003e/dev/null \u0026\u0026 pgrep -x open5gs-amfd \u003e/dev/null \u0026\u0026 pgrep -x open5gs-upfd \u003e/dev/null"
