      "networks": {
        "core": {
          "ipv4_address": "10.53.0.4"
        }
      },
      "restart": "no",
      "volumes": [
        {
          "type": "bind",
          "source": "C:\\Users\\devel\\Documents\\Codex\\2026-08-22\\he\\safetwin-5g\\sandbox\\config\\ueransim\\gnb.yaml",
          "target": "/etc/ueransim/gnb.yaml",
          "read_only": true,
          "bind": {}
        }
      ]
    },
    "ueransim-ue": {
      "cap_add": [
        "NET_ADMIN",
        "NET_RAW"
      ],
      "command": [
        "/opt/ueransim/bin/nr-ue",
        "-c",
        "/etc/ueransim/ue.yaml"
      ],
      "container_name": "safetwin5g-ue",
      "depends_on": {
        "ueransim-gnb": {
          "condition": "service_healthy",
          "required": true
        }
      },
      "devices": [
        {
