        }
      },
      "restart": "no",
      "volumes": [
        {
          "type": "bind",
          "source": "C:\\Users\\devel\\Documents\\Codex\\2026-08-22\\he\\safetwin-5g\\sandbox\\config\\ueransim\\ue.yaml",
